const { url } = globalThis.input;
try {
  const response = await fetch(url);
  if (!response.ok) throw new Error('HTTP error ' + response.status);
  const body = await response.text();
  globalThis.rawBody = body;
} catch (e) {
  throw new Error('fetch failed: ' + (e && e.message ? e.message : e));
}

if (!globalThis.rawBody) throw new Error('parse failed: no raw body');
const snippet = globalThis.rawBody.slice(0, 200);
globalThis.sectionsStr = JSON.stringify([{ heading: '', text: snippet }]);
